  ["b60eaaa37201c672"] = { "Be', sei ancora qui. Direi che merita un brindisi.", "." },
  ["b6157fe2c6ad3600"] = { "Andiamo, {name}. Possiamo partire per l'⟦Whitereach Post=Accampamento di Manto Bianco⟧.", "." },
