  ["b64468e0338e8027"] = { "Sto studiando un modo per trasportare il petrolio sottoterra tra le grandi città, ma tutti mi dicono che è un sogno nel tubo.", "." },
  ["b644828e134d4b3a"] = { "Muoviamoci. La mia attrezzatura dovrebbe essere nel magazzino, da questa parte...", "." },
  ["b64556382a07b0e2"] = { "Ho finito, <fratello/sorella>. Finisci tu. Io me ne torno a riposare sulla roccia.", "." },
  ["b64ca9b418a06cc6"] = { "Incredibile! Come hai fatto a ottenere un dominio permanente?", "." },
  ["b64cafa4362320c3"] = { "I ⟦Dark Iron Dwarves=Nani Ferroscuro⟧ reclameranno le terre che spettano loro!", "." },
  ["b65111aff84fbaf9"] = { "STOLTO! HAI PERMESSO A QUESTI INSETTI DI SCORRAZZARE NEL SACRO NUCLEO? E ORA LI CONDUCI FINO AL MIO COVO? MI HAI DELUSO, EXECUTUS! GIUSTIZIA SARÀ FATTA, EH SÌ!", "." },
  ["b6523f4805baef4b"] = { "Ottieni una scheda dati di alto livello.", "." },
  ["b6598e9fb586805c"] = { "%s emerge dal terreno!", "." },
  ["b661f8dcf78b8e63"] = { "Non voglio farti del male. Sto spiando i verrospini e prendo nota delle loro attività. La mia gente ha notato qualcosa di strano, un'emanazione, una tenebra, provenire da questa zona. Mi hanno mandato a indagare, e ciò che ho scoperto è molto inquietante.\n\nSembra che ci sia un diplomatico non morto molto potente nelle arti arcane. Non credo che sia uno dei Reietti... Credo che sia qualcosa di peggio.", "." },
  ["b665d5509bf460db"] = { "Per Gnomeregan!", "." },
  ["b665fd8ee3491b30"] = { "Ciao di nuovo, {name}! Che bello vederti! La nostra ⟦Darkmoon Faire=Fiera di Lunacupa⟧ è proprio uno spettacolo, non trovi?\n\nC'è tanto da vedere! Quindi guarda! Guarda, e forse un giorno ti verrà rivelato ancora di più...", "." },
  ["b6673cdd6c4e6aaa"] = { "Nasconditi nell'ombra. Abbiamo affari da discutere, appena avrò finito di mostrare a queste bestie perché mi chiamano la Mano del Caos.", "." },
  ["b66b0ed6c77bf1df"] = { "Hammertoe, sei intelligente quanto eri testardo in vita, e anche nella morte. Cosa puoi dirmi, vecchio amico?", "." },
  ["b66ec1a413f3cf23"] = { "Le mie conoscenze sono limitate, anche se continuo a imparare. È tempo che tu vada oltre, viaggiatore. Trova Josef Gregorian a ⟦Undercity=Sepulcra⟧ e digli che sei <pronto/pronta>.", "." },
  ["b66ede1d56912720"] = { "Va' a riferire che l'avamposto è stato preso. Noi resteremo qui.", "." },
  ["b670bbc198674448"] = { "Ti hanno fregato per bene con quella, ragazzo!", "." },
  ["b6731e4d9c8ebe73"] = { "Wushoolay, la Strega della Tempesta.\n\nIl suo potere è il potere del cielo, della pioggia e della terra frantumata. Possa ella regnare di nuovo come madre dei Gurubashi.\n\nWushoolay ora dimora lontano da qui. Un giorno, forse, tornerà...", "." },
  ["b673a674fa781b82"] = { "Ah! Meglio mille volte il botto di un Crater Cannon XT che spara un colpo!", "." },
  ["b675196ddac1fde7"] = { "Se vuoi imparare a forgiare da te armi e armature, sarò felice di aiutarti.", "." },
  ["b679820c222dc985"] = { "Credo che tu sia più che all'altezza di questo piccolo incarico... vediamo se ho ragione!", "." },
  ["b67dd5fe44d5d6c0"] = { "Solo uno sciocco oserebbe disturbarmi nella mia tana.", "." },
  ["b67e9b03805d87af"] = { "Il Flagello sta allestendo piccoli punti di raccolta nei luoghi sotto attacco, e riceve comunicazioni e altri aiuti dalle necropoli che volano sopra di noi. Da quanto possiamo capire, l'unico modo per sradicarli è uccidere le forze di terra che circondano quei punti.", "." },
  ["b68491d4fce35f98"] = { "Metti fine alla nostra sofferenza!", "." },
  ["b6955ea75d11017d"] = { "Stammi lontano, mostro!", "." },
  ["b695ffafa64ff0b3"] = { "Di solito gli scuoiatori portano tutte le pelli a ⟦Ironforge=Forgiardente⟧ per farle seccare. Perché non vai lì a cercarne uno che ti addestri?", "." },
  ["b696c3d3f3f2f884"] = { "Sei <sicuro/sicura> di essere <pronto/pronta>? Se non avremo un gruppo di tuoi alleati ad aiutarci, falliremo di certo.", "." },
  ["b6a387100192cdca"] = { "Cerca Kaplak in cima alla tana, nella zona sud-occidentale della città.", "." },
  ["b6a6007e6dac3f20"] = { "Oh, grazie! Questo incubo mi teneva in trappola da tanto tempo...", "." },
  ["b6a6db5803234505"] = { "Mi è negato per sempre il tocco della pietra. Non conoscerò mai più la gloria del ferro forgiato...", "." },
  ["b6a9db9e76136bef"] = { "Sento qualcosa! Dev'essere Chambers che arriva. Fate largo! Fate largo!", "." },
  ["b6b121e6af35995c"] = { "%s ruggisce mentre cambia forma e fugge via.", "." },
  ["b6b5e1885ffdfe0f"] = { "Mi serve un'altra pietra scintillante.", "." },
  ["b6b88248f2014565"] = { "Ehi, {name}! Non dimenticare di prendere una cassa, un manuale e un bastone di comando!", "." },
  ["b6bc541b11548da9"] = { "Una volta costruito il congegno, basta attivarlo per essere portati via nella splendida ⟦Gadgetzan=Meccania⟧! Quasi tutti quelli che hanno usato il congegno sono arrivati qui sulla piattaforma con lo stesso aspetto che avevano alla partenza!\n\nCi sono state alcune segnalazioni di persone trasportate e sostituite dalle loro versioni malvagie di un universo alternativo, ma di sicuro risolveremo presto la cosa...", "." },
  ["b6be6c945bc7d7aa"] = { "Cosa sai della ⟦Shady Rest Inn=Locanda Ombracalma⟧?", "." },
  ["b6c41e2231be9e8c"] = { "Se brami la via del Guerriero, devi cercare ⟦Krang Stonehoof=Krang Zoccolo Granitico⟧. Lo troverai nell'angolo sud-orientale del villaggio, nel suo cerchio d'addestramento, spesso intento a istruire altri allievi.", "." },
  ["b6c4cad4e798a2f0"] = { "Ti stavo aspett...\n\n<Rimblat tossisce.>\n\nScusami, vecchia abitudine. Sono Rimblat del Circolo della Terra.", "." },
  ["b6c96d4531a69f0e"] = { "Faranno fuochi d'artificio per tutta la notte. Dalle sei di sera fino all'alba, il cielo sopra Elune'ara sarà in fiamme!", "." },
  ["b6d3df6e9196dd90"] = { "Direi di no, non ho bisogno di saltare in aria un'altra volta.", "." },
  ["b6d4ebe261cefe29"] = { "Questa spedizione prosciuga terribilmente le scorte militari.", "." },
  ["b6de272a4f8ab8cc"] = { "Preparatevi, perché presto lanceremo un assalto contro coloro che si fanno chiamare «i Reietti».", "." },
  ["b6dee6b37ab8ac75"] = { "<Fa schioccare i denti, mordicchiando il morso.>", "." },
  ["b6e37bf318ac5330"] = { "Ben fatto, ⟦Horde=Orda⟧! Nelle nostre stalle ci sono abbastanza lupi bianchi da dare una cavalcatura a tutti i nostri cavalieri di lupi!", "." },
  ["b6e719b052eb2633"] = { "Wow! Pare che abbiamo già raccolto tutto il cuoio spesso che secondo loro ci serve. È andata proprio in fretta. Sai, qui intorno c'è di sicuro qualcun altro a cui farebbe comodo il tuo aiuto, se vuoi dargli una mano.", "." },
  ["b6ee3be986338545"] = { "Sei qui a prendere servizio, {class}? Tutto il materiale bellico sia dell'⟦Horde=Orda⟧ sia dell'⟦Alliance=Alleanza⟧ è completato e viene spedito a ⟦Silithus=Silitus⟧ proprio ora. Dovrebbe arrivare tutto in meno di $2113w giorni. Spero che qualcuno abbia trovato i vari pezzi dello Scettro delle Sabbie Mutevoli e li abbia rimessi insieme.", "." },
  ["b6f352abd7a54393"] = { "Grazie a te, {name}.", "." },
  ["b6f3b169ff67abf5"] = { "Ecco... Questi sassi dovrebbero bastare per fare una collana. Comunque ora farei meglio a tornare a casa.", "." },
